import react from '@vitejs/plugin-react';
import { execFile } from 'node:child_process';
import { sep } from 'node:path';
import { defineConfig, type Plugin } from 'vite';

/**
 * Dev only: data/runtime/*.json is built from data/generated by scripts/build-runtime-data.mjs, and
 * the site's split data (public/assets/d/, data/runtime/split-index.json) from that by
 * scripts/split/build.mjs (predev/prebuild). When a pipeline script rewrites data/generated during a dev session, rebuild
 * the runtime files and reload the page, so the change shows without restarting the server.
 */
function runtimeData(): Plugin {
  return {
    name: 'aru-runtime-data',
    apply: 'serve',
    configureServer(server) {
      const watched = `${sep}data${sep}generated${sep}`;
      let timer: NodeJS.Timeout | undefined;
      const rebuild = (file: string) => {
        if (!file.includes(watched) || !file.endsWith('.json')) return;
        clearTimeout(timer);
        // pipeline scripts often write several files in a row: wait for the last one
        timer = setTimeout(() => {
          execFile(process.execPath, ['scripts/build-runtime-data.mjs'], { cwd: server.config.root }, (err, stdout, stderr) => {
            if (err) { server.config.logger.error(`runtime data: ${stderr || err.message}`); return; }
            execFile(process.execPath, ['scripts/split/build.mjs'], { cwd: server.config.root }, (err2, stdout2, stderr2) => {
              if (err2) { server.config.logger.error(`split data: ${stderr2 || err2.message}`); return; }
              server.config.logger.info(`runtime data rebuilt\n${stdout.trim()}\n${stdout2.trim()}`, { timestamp: true });
              server.ws.send({ type: 'full-reload' });
            });
          });
        }, 300);
      };
      server.watcher.on('change', rebuild);
      server.watcher.on('add', rebuild);
    },
  };
}

export default defineConfig({
  plugins: [react(), runtimeData()],
  // Reached through an SSH tunnel (ssh -L 5173:localhost:5173 ...), so bind to loopback only.
  // /api/report and /api/suggest go to scripts/report-server.mjs when it runs locally (in production Caddy does this)
  server: { host: '127.0.0.1', port: Number(process.env.PORT ?? 5173), strictPort: true, proxy: { '/api': 'http://127.0.0.1:8787' } },
});
